import{_ as e,o as a,c as d,a2 as r}from"./chunks/framework.DSoq407f.js";const u=JSON.parse('{"title":"环境要求","description":"","frontmatter":{},"headers":[],"relativePath":"deploy/requirements.md","filePath":"deploy/requirements.md","lastUpdated":1786505997000}'),o={name:"deploy/requirements.md"};function n(s,t,i,l,h,c){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="环境要求" tabindex="-1">环境要求 <a class="header-anchor" href="#环境要求" aria-label="Permalink to &quot;环境要求&quot;">​</a></h1><blockquote><p>部署 V3 前，请准备好以下环境。</p></blockquote><h2 id="服务器要求" tabindex="-1">服务器要求 <a class="header-anchor" href="#服务器要求" aria-label="Permalink to &quot;服务器要求&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>最低</th><th>推荐</th></tr></thead><tbody><tr><td>CPU</td><td>2 核</td><td>4 核</td></tr><tr><td>内存</td><td>2 GB</td><td>4 GB</td></tr><tr><td>磁盘</td><td>20 GB</td><td>50 GB+</td></tr><tr><td>操作系统</td><td>CentOS 7+ / Ubuntu 20.04+ / Debian 10+</td><td>Ubuntu 22.04 / Debian 12</td></tr></tbody></table><h2 id="必需组件" tabindex="-1">必需组件 <a class="header-anchor" href="#必需组件" aria-label="Permalink to &quot;必需组件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组件</th><th>版本</th><th>说明</th></tr></thead><tbody><tr><td><strong>Docker Engine</strong></td><td>24+</td><td>运行容器（推荐方式）</td></tr><tr><td><strong>Docker Compose</strong></td><td>v2</td><td>编排容器</td></tr><tr><td><strong>PostgreSQL</strong></td><td>13+</td><td>主数据库，<strong>需自备</strong>，V3 不内置</td></tr><tr><td><strong>域名</strong></td><td>—</td><td>绑定授权用，建议已备案并解析到服务器</td></tr></tbody></table><h2 id="可选组件" tabindex="-1">可选组件 <a class="header-anchor" href="#可选组件" aria-label="Permalink to &quot;可选组件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组件</th><th>版本</th><th>说明</th></tr></thead><tbody><tr><td><strong>Redis</strong></td><td>6+</td><td>提升事件通知性能；不装也能跑，自动降级</td></tr><tr><td><strong>Nginx</strong></td><td>—</td><td>反向代理 + HTTPS，生产环境强烈推荐</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">数据库要自备</p><p>V3 容器<strong>不包含</strong> PostgreSQL。你需要自行准备一个 PostgreSQL 数据库（云数据库 RDS 或服务器自建均可），在安装向导里填连接地址。</p></div><div class="warning custom-block"><p class="custom-block-title">Redis 的作用</p><p>Redis 只影响<strong>性能</strong>，不影响功能正确性。有 Redis 时事件通知更快；没有时自动降级为数据库轮询。小规模部署可以不装，但建议生产环境配上。</p></div><h2 id="网络" tabindex="-1">网络 <a class="header-anchor" href="#网络" aria-label="Permalink to &quot;网络&quot;">​</a></h2><ul><li>开放一个端口给 V3 容器（默认 <code>8000</code>），或通过 Nginx 反代。</li><li>服务器需能访问授权云服务（用于域名授权校验）。</li><li>如使用 Webhook 类适配器（QQ 官方等），平台需能从公网回调到你的服务器。</li></ul><h2 id="授权准备" tabindex="-1">授权准备 <a class="header-anchor" href="#授权准备" aria-label="Permalink to &quot;授权准备&quot;">​</a></h2><p>V3 是闭源商业产品，部署前需要：</p><ol><li>在授权平台（sq.yuafeng.cn）把你的<strong>部署域名</strong>登记并绑定授权。</li><li>部署时安装向导会根据访问域名<strong>自动获取授权码</strong>；如自动获取失败，可手动粘贴授权码。</li></ol><p>详见 <a href="./authorization">授权激活</a>。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>环境就绪 → <a href="./docker">Docker 部署</a></p>',18)])])}const p=e(o,[["render",n]]);export{u as __pageData,p as default};
